// The day's affirmation in Slovak, for the country pages in Slovak. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Dnes nemusíš zvládnuť všetko. Stačí tá ďalšia malá vec.\", \"Únava nie je zlyhanie. Si unavená, pretože si tu pre nich každý deň.\", \"Riad počká. Môžeš si na päť minút sadnúť.\", \"Cereálie na večeru sa tiež rátajú ako nakŕmená rodina.\", \"Oddych si nemusíš zaslúžiť. Pokojne si oddýchni hneď teraz.\", \"Niekedy je víťazstvom už to, že všetci vydržali až do spania. To je skutočné víťazstvo.\", \"Robíš viac, než ktokoľvek vidí. Ja to vidím.\", \"Neuprataný byt a milované deti. To je dobrá výmena.\", \"V ťažký deň vyzerá tvoje maximum inak, a aj tak sa ráta.\", \"Jeden hlboký nádych. Spusti plecia. Zvládaš to.\", \"Dnes je v poriadku znížiť latku. Zdvihnúť ju môžeš inokedy.\", \"Požiadať o pomoc je prejav sily, nie slabosti.\", \"Máš právo povedať nie ďalšej veci navyše.\", \"Ak si sa dnes cítila osamelo, nie si jediná mama, ktorá to tak mala. Je nás veľa.\", \"Zaslúžiš si kamarátku, ktorá sa spýta, ako sa máš, a počká na odpoveď.\", \"Pokojne sa ozvi ako prvá. Väčšina mám dúfa, že to niekto urobí.\", \"To, že sa cítiš neviditeľná, neznamená, že na tebe nezáleží. Záleží na tebe veľmi.\", \"Tvoje pocity dávajú zmysel. Nie si „priveľa“.\", \"Tu nemusíš svoj ťažký deň vysvetľovať. Rozumieme.\", \"Správa inej mame so slovami „aj ja“ dokáže otočiť celý deň.\", \"Kŕmenie, prebaľovanie, hojdanie a stále dokola. To je skutočná práca, aj keď to vyzerá ako sedenie na mieste.\", \"Ty a tvoje bábätko sa ešte stále spoznávate. Netreba sa ponáhľať.\", \"Dni s novorodencom sú dlhé. Toto obdobie nebude trvať večne.\", \"Ak si dnes iba udržala malého človiečika najedeného a v teple, urobila si veľký kus práce.\", \"Nemusíš byť hneď zase vo forme. Môžeš byť jednoducho tam, kde si.\", \"Nech kŕmiš bábätko akokoľvek, staráš sa oň. To je to, čo sa ráta.\", \"Môžeš byť nevyspatá a zároveň plná lásky.\", \"Pochovaj bábätko a domácnosť nechaj tak. Tá tu bude aj potom.\", \"Záchvat zlosti v obchode z teba nerobí zlú mamu. Znamená len, že máš batoľa.\", \"Malí skúšajú hranice, pretože sa pri tebe cítia v bezpečí.\", \"Dnes si zostala pokojná o minútu dlhšie ako včera. To sa ráta.\", \"Ak ti ušli nervy, objatie a „prepáč“ napravia veľa. A naučia ich niečo dobré.\", \"Ulepené rúčky, hlasné hlasy, veľké emócie. Vychovávaš celého človeka.\", \"Piate „prečo?“ za hodinu je malá hlávka, ktorá rastie.\", \"Na šťastnú spomienku nepotrebuješ dokonalý deň.\", \"Tresnuté dvere nie sú koniec príbehu. Nechaj svetlo zažaté.\", \"Tvoj tínedžer to možno nepovie, ale to, že si stále nablízku, je dôležité.\", \"Byť tou pokojnou v dome je drina. A ty to robíš.\", \"Niektoré z najlepších rozhovorov sa odohrajú v aute. Len jazdi ďalej.\", \"Vzďaľujú sa, aby dospeli, nie aby ťa nechali za sebou.\", \"Nemusíš poznať všetky odpovede. Počúvanie je veľká časť toho všetkého.\", \"Veľké deti ťa stále potrebujú, len tichšie.\", \"Zvládať všetko sama si žiada silu, ktorú väčšina ľudí nikdy neuvidí.\", \"Pre svoje dieťa si dosť dobrá mama. Vždy si bola.\", \"Jedny ruky, sto úloh. Buď k sebe láskavá.\", \"Tvoje deti sa od teba učia, ako vyzerá silný a láskavý človek.\", \"Prestávka neznamená opustiť svoje miesto. Vďaka nej vydržíš.\", \"Nikto nepočíta body. Záleží na láske a na tom, že si tu.\", \"Smútok a láska pramenia z rovnakého miesta. To, ako veľmi ti niekto chýba, ukazuje, ako veľmi si milovala.\", \"Na smútenie neexistuje správny harmonogram. Daj si toľko času, koľko potrebuješ.\", \"V ťažké výročia buď k sebe taká jemná, ako by si bola ku kamarátke.\", \"Môžeš v sebe niesť smútok a aj tak sa smiať so svojimi deťmi. Oboje je skutočné.\", \"Ak si prišla o tehotenstvo alebo o bábätko, tá strata je skutočná a tvoja láska tiež.\", \"Niektoré dni je smútok tichý a niektoré hlasný. Oboje je v poriadku.\", \"Málo peňazí neznamená málo lásky.\", \"Tvoje deti si budú pamätať čas s tebou viac než veci, ktoré si kúpila.\", \"Opýtať sa na pomoc s účtami je múdre, nie hanebné. Práve na to tá pomoc existuje.\", \"Popoludnie v parku zadarmo môže byť najlepší deň v týždni.\", \"Vyšla si s peniazmi o týždeň dlhšie. To si vyžaduje skutočné umenie.\", \"Starosti o peniaze vyčerpávajú. Nesieš toho veľa, a stále si tu.\", \"Dnes si vypila pohár vody. Začni tým.\", \"Všetci vyšli z domu. Topánky možno neladili. Aj tak je to víťazstvo.\", \"Zavolala si tam, kam sa ti tak nechcelo. To bolo odvážne.\", \"Dnes si sa smiala. Drž sa toho.\", \"Teplé jedlo, čisté tričko, rozprávka na dobrú noc. Z malých vecí sa skladá detstvo.\", \"Dnes si bola k niekomu láskavá, aj keby to bola len ty sama.\", \"Pokrok, nie dokonalosť. Dnes si sa posunula dopredu.\", \"Dokončila si jednu vec zo zoznamu. To je o jednu viac ako žiadna.\", \"Si dobrá mama. To, že si s tým robíš starosti, ukazuje, ako veľmi ti na tom záleží.\", \"Si viac než to, čo za deň stihneš.\", \"Tvoje deti nepotrebujú dokonalú mamu. Potrebujú teba, a teba majú.\", \"Maj so sebou rovnakú trpezlivosť, akú máš so svojimi deťmi.\", \"Máš právo zaberať miesto, niečo chcieť a mať vlastné sny.\", \"Chyba lásku nezmaže. Zajtra je nový začiatok.\", \"Pre niekoho si celý svet, a zároveň si aj sama sebou.\", \"Je v poriadku neužívať si každú minútu. Svoje deti môžeš aj tak milovať celým srdcom.\", \"Neexistuje jediný správny spôsob, ako byť mamou. Tvoj spôsob je v poriadku.\", \"Ako v pozícii stromu je v poriadku zakolísať. Rovnováhu znova nájdeš.\", \"Pevne sa postav ako v pozícii hory. Stojíš pevnejšie, než sa cítiš.\", \"Bojovník II: silné nohy, otvorená náruč. To si ty, keď čelíš tomuto týždňu.\", \"Nádych na štyri, výdych na štyri. Si tu a zvládaš to.\", \"Roztiahni sa doširoka ako hviezda. Máš právo zaberať miesto.\", \"Široký, hlboký drep sa ťažko drží. Dlhý deň tiež. A ty ho držíš.\", \"Môžeš sa nakloniť ako kosák mesiaca a stále stáť.\", \"Na špičky prstov ešte dosiahnuť nemusíš. Každý kúsok natiahnutia sa ráta.\", \"Pozícia trojuholníka: jedna ruka dole, druhá hore. Stoj pevne a naťahuj sa ďalej.\", \"Je neskoro. Čo sa dnes nestihlo, počká do zajtra.\", \"V túto hodinu hore s bábätkom? Veľa mám je práve teraz hore s tebou.\", \"V dome je ticho. Táto chvíľa je tvoja. Dýchaj.\", \"Zvládla si dnešok. Viac dnešok nepotreboval.\", \"Ak ti dnes v noci beží hlava, zapíš si to a nechaj to počkať do rána.\", \"Zavri oči a oddýchni si. Zajtra môžeš začať odznova.\", \"Sviatky môžu byť ťažké, nielen radostné. Nech je pre teba toto obdobie akékoľvek, je to v poriadku.\", \"Stôl nemusí byť dokonalý. Záleží na ľuďoch okolo neho.\", \"Ak ti tento rok pri stole niekto chýba, buď k svojmu srdcu nežná.\", \"Ďakujem, mami, za každé jedlo, každé odvezenie a každé objatie.\", \"Nemusíš hostiť, piecť ani sa stále usmievať. Jednoduché sviatky sú stále sviatky.\", \"Najlepší darček, ktorý tvoje deti tento rok dostanú, je čas s tebou.\", \"Malé sviatky sú tiež plné lásky. Aby boli výnimočné, netreba veľa peňazí.\", \"Studené dni, teplé objatia. Ty si to teplé miesto vo svojom domove.\", \"Je v poriadku vynechať časť sviatočného zhonu. Pokoj je tiež darček.\", \"Ak je pre teba tento rok toto obdobie ťažké, nie si sama. Deň po dni.\"]";D.body.appendChild(e)})();
